/**
 * Jinx Al-Hadikhia + Mastermind: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Al-Hadikhia
 * Wiki: https://wiki.bloodontheclocktower.com/Mastermind
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L119). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData } from '#lib/core/testing/committed-data.ts';
import { gameEnds } from '#lib/core/rules/game-end/game-end.ts';
import { ownJinxRules } from '#lib/core/rules/jinxes/jinxes.ts';
import { scenario, type Scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Al-Hadikhia + Mastermind jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'alhadikhia', 'mastermind');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('alhadikhia')?.name).toBe('Al-Hadikhia');
		expect(data.byId.get('mastermind')?.name).toBe('Mastermind');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['alhadikhia', 'mastermind'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['alhadikhia'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['mastermind'])).not.toContain(jinx);
	});

	describe('the executed Al-Hadikhia chooses 3 good players instead of an extra day', () => {
		const ids = ['alhadikhia', 'mastermind', 'chef', 'empath', 'monk', 'soldier'];
		const base = scenario(ids, { script: scriptOf(ids) });
		const demonDead = (s: Scenario) =>
			gameEnds(s.game, s.characters).find((e) => e.rule === 'demon-dead');

		it("is data in the Mastermind's rules", () => {
			// Wiki: "If the Al-Hadikhia dies by execution, and the Mastermind is alive, the Al-Hadikhia chooses 3 good players tonight: if all 3 choose to live, evil wins. Otherwise, good wins."
			expect(ownJinxRules(base.game, 'mastermind', 'alhadikhia', base.characters)).toEqual({
				endsGame: { kind: 'night-instead', chooser: 'partner' }
			});
		});

		it('keeps the game going for that night, with no extra day', () => {
			// Wiki: "the Al-Hadikhia chooses 3 good players tonight"
			const s = base.execute('alhadikhia');
			expect(demonDead(s)?.holds).toMatchObject([
				{ rule: 'jinx-night', characterId: 'alhadikhia', seats: [s.seat('mastermind')] }
			]);
		});

		it('gives no extra-day end the next day: that night’s choice decides', () => {
			// Wiki: "if all 3 choose to live, evil wins. Otherwise, good wins."
			const s = base.execute('alhadikhia').dusk().newDay().execute('chef');
			expect(gameEnds(s.game, s.characters).some((e) => e.rule === 'extra-day')).toBe(false);
		});

		it('ends the game as usual once the Mastermind is dead', () => {
			// Wiki: "and the Mastermind is alive"
			const s = base.dies('mastermind').execute('alhadikhia');
			expect(demonDead(s)?.holds).toEqual([]);
		});
	});
});
